}

const optimisticUpserts =
  options?.optimisticUpserts ?? this.optimisticUpserts
const optimisticDeletes =
  options?.optimisticDeletes ?? this.optimisticDeletes
const hasOptimisticChange =
  optimisticUpserts.has(key) ||
